changeSet.sql:
ALTER TABLE document.contracts ADD COLUMN IF NOT EXISTS access_code VARCHAR(8);

UPDATE document.contracts
   SET access_code = lpad((floor(random() * 10000))::int::text, 4, '0')
 WHERE access_code IS NULL;

UPDATE document.contracts
   SET pdf_generated_at = NULL,
       pdf_generated_at_ru = NULL,
       pdf_generated_at_en = NULL;
